const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeMenindee = ee.Geometry.Polygon([
    [[142.0, -32.3], [142.4, -32.3], [142.4, -32.5], [142.0, -32.5], [142.0, -32.3]]
  ]);

  const date1 = '2019-02-02';
  const date2 = '2021-05-14';

  // 2. Data Acquisition - Sentinel-2
  function getWaterCollection(date) {
    return ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(lakeMenindee)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20));
  }

  const col1 = getWaterCollection(date1);
  const col2 = getWaterCollection(date2);

  // Check collection sizes
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`2019-02-02 Images: ${size1}`);
  console.log(`2021-05-14 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate water extent
  function calculateWaterArea(image) {
    // Calculate NDWI for water detection
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Water mask (NDWI > 0.0)
    const waterMask = ndwi.gt(0.0);

    // Count water pixels
    const waterCount = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: lakeMenindee,
      scale: 100,
      maxPixels: 1e9
    }).get('NDWI');

    return waterCount;
  }

  const waterArea1 = calculateWaterArea(col1.first());
  const waterArea2 = calculateWaterArea(col2.first());

  const area1 = waterArea1.getInfo();
  const area2 = waterArea2.getInfo();

  console.log(`2019 Water Pixels: ${area1}`);
  console.log(`2021 Water Pixels: ${area2}`);

  // 4. Validation & Final Answer
  if (area1 === null || area2 === null || isNaN(area1) || isNaN(area2)) {
    console.log("<answer>C3</answer>");
  } else if (area1 === 0 || area2 === 0) {
    console.log("<answer>C2</answer>");
  } else if (area2 < area1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
